import { getAdminParams, type ReactAdminSvgFileItem, type ReactAdminImageFileItem, type ReactAdminMarkerImageItem } from "./admin-params"
import { adminRestFetch } from "./admin-rest-fetch"
import { resourceApiUrl } from "./resource-api-url"

export type Catalogs = { svg: ReactAdminSvgFileItem; image: ReactAdminImageFileItem; markers: ReactAdminMarkerImageItem }
export type CatalogKind = keyof Catalogs
type File = Catalogs[CatalogKind]
const flights = new Map<string, Promise<File[]>>()
const cache = new Map<string, File[]>()

function bootstrap<K extends CatalogKind>(kind: K): Catalogs[K][] {
  const params = getAdminParams()
  return (kind === "svg" ? params.svgFiles : kind === "image" ? params.imageFiles ?? [] : params.markerImages) as Catalogs[K][]
}

/** Fresh managed revisions win over stale props; newly uploaded files remain visible. */
export function mergeCatalogFiles<T extends File>(files: T[], additions: T[]): T[] {
  const key = (file: T) => "assetId" in file && file.assetId ? `asset:${file.assetId}` : file.relativeUrl
  const originals = new Set([...files, ...additions].flatMap(file => "assetId" in file && file.assetId && "originalUrl" in file && file.originalUrl ? [file.originalUrl] : []))
  const visible = (file: T) => "assetId" in file && file.assetId || !originals.has(file.relativeUrl)
  const result = new Map(files.filter(visible).map(file => [key(file), file]))
  for (const file of additions) {
    if (!visible(file)) continue
    const previous = result.get(key(file))
    if (!previous || ("revisionId" in file && (file.revisionId ?? 0) > ((previous as ReactAdminSvgFileItem).revisionId ?? 0))) result.set(key(file), file)
  }
  return [...result.values()]
}

/** One read per kind/site/user at a time, independent of any one picker's lifecycle. */
export function loadAdminCatalog<K extends CatalogKind>(kind: K): Promise<Catalogs[K][]> {
  const params = getAdminParams()
  if (!params.deferredCatalogs) return Promise.resolve(bootstrap(kind))
  const key = JSON.stringify([params.apiUrl, params.user.id, kind])
  const pending = flights.get(key)
  if (pending) return pending as Promise<Catalogs[K][]>
  // SVG revisions and raster uploads may also change through another editor/chat.
  if (kind === "markers" && cache.has(key)) return Promise.resolve(mergeCatalogFiles(cache.get(key) as Catalogs[K][], bootstrap(kind)))
  const url = new URL(resourceApiUrl(params.apiUrl, "/admin-catalogs"), window.location.href)
  url.searchParams.set("kind", kind)
  const controller = new AbortController()
  const timer = window.setTimeout(() => controller.abort(), 15000)
  const request = adminRestFetch(url.href, { signal: controller.signal, credentials: "same-origin", cache: "no-store", headers: { Accept: "application/json", "X-WP-Nonce": params.nonce } })
    .then(async response => {
      const data = await response.json()
      if (!response.ok || !Array.isArray(data?.files)) throw new Error(data?.message ?? "The file library could not be loaded.")
      if (data.files.some((file: unknown) => !file || typeof file !== "object" || ["name", "relativeUrl", "pathShort"].some(field => typeof (file as Record<string, unknown>)[field] !== "string"))) throw new Error("The server returned an invalid file library.")
      const files = mergeCatalogFiles(data.files as Catalogs[K][], bootstrap(kind))
      if (kind === "markers") cache.set(key, files)
      return files
    }).catch(failure => {
      if (controller.signal.aborted) throw new Error("The file library took too long to load. Please retry.")
      throw failure
    }).finally(() => { window.clearTimeout(timer); if (flights.get(key) === request) flights.delete(key) })
  flights.set(key, request)
  return request
}
