import { useEffect, useMemo, useState } from "react"
import { loadAdminCatalog, mergeCatalogFiles, type CatalogKind, type Catalogs } from "./admin-catalogs"

/** Retire only this observer on close/unmount; a shared read may serve another picker. */
export function useAdminCatalog<K extends CatalogKind>(kind: K, active: boolean, existing: Catalogs[K][]) {
  const [files, setFiles] = useState<Catalogs[K][]>([])
  const [loading, setLoading] = useState(false)
  const [settled, setSettled] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [attempt, setAttempt] = useState(0)
  useEffect(() => {
    if (!active) { setLoading(false); setSettled(false); return }
    let retired = false
    setLoading(true)
    setError(null)
    void loadAdminCatalog(kind).then(next => { if (!retired) setFiles(next) })
      .catch(failure => { if (!retired) setError(failure instanceof Error ? failure.message : "The file library could not be loaded.") })
      .finally(() => { if (!retired) { setLoading(false); setSettled(true) } })
    return () => { retired = true }
  }, [kind, active, attempt])
  const merged = useMemo(() => mergeCatalogFiles(files, existing), [files, existing])
  return { files: merged, loading: active && (!settled || loading), error, retry: () => { setLoading(true); setAttempt(value => value + 1) } }
}
